sys_script_include.script:
var GetDeviceDescription = Class.create();
GetDeviceDescription.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    getDescription: function() {
        var deviceSysId = this.getParameter('sysparm_device');
        var gr = new GlideRecord('u_ai_devices'); // your table name
        if (gr.get(deviceSysId)) {
            return gr.description.toString();
        }
        return '';
    }
});
